// Shared Tailwind class helpers for the representative sign-up wizard steps.
export const labelCls =
  "tw-mb-1.5 tw-block tw-text-sm tw-font-semibold tw-text-[#14101c]";

export const inputCls =
  "tw-w-full tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-bg-white tw-px-3.5 tw-py-2.5 tw-text-sm tw-text-[#14101c] tw-outline-none tw-transition focus:tw-border-[#854ec9] focus:tw-shadow-[0_0_0_3px_rgba(133,78,201,0.12)]";

export const pillCls = (active: boolean) =>
  `tw-cursor-pointer tw-select-none tw-rounded-full tw-border tw-border-solid tw-px-4 tw-py-2 tw-text-sm tw-font-medium tw-transition-all ${
    active
      ? "tw-border-[#854ec9] tw-bg-[#854ec9] tw-text-white tw-shadow-[0_6px_16px_rgba(133,78,201,0.30)]"
      : "tw-border-[#e2dded] tw-bg-white tw-text-[#5d556c] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9]"
  }`;
